class TwoSAT {
  constructor(n){this.n=n;this.adj=Array.from({length:2*n},()=>[]);this.radj=Array.from({length:2*n},()=>[]);}
  addClause(x,y){const notX=x<this.n?x+this.n:x-this.n;const notY=y<this.n?y+this.n:y-this.n;this.adj[notX].push(y);this.adj[notY].push(x);this.radj[y].push(notX);this.radj[x].push(notY);}
  solve(){
    const n2=2*this.n;const visited=new Array(n2).fill(false);const order=[];
    const dfs1=(v)=>{visited[v]=true;for(const u of this.adj[v])if(!visited[u])dfs1(u);order.push(v);};
    for(let v=0;v<n2;v++)if(!visited[v])dfs1(v);
    const comp=new Array(n2).fill(-1);let sccId=0;
    const dfs2=(v,id)=>{comp[v]=id;for(const u of this.radj[v])if(comp[u]===-1)dfs2(u,id);};
    for(let i=n2-1;i>=0;i--){if(comp[order[i]]===-1){dfs2(order[i],sccId);sccId++;}}
    const assignment=new Array(this.n);
    for(let i=0;i<this.n;i++){if(comp[i]===comp[i+this.n])return null;assignment[i]=comp[i]>comp[i+this.n];}
    return assignment;
  }
}

