class SparseTable {
  constructor(arr){const n=arr.length;const LOG=Math.floor(Math.log2(n))+1;this.log2=new Int32Array(n+1);this.log2[1]=0;for(let i=2;i<=n;i++)this.log2[i]=this.log2[i>>1]+1;this.table=Array.from({length:n},(_,i)=>new Int32Array(LOG));for(let i=0;i<n;i++)this.table[i][0]=arr[i];for(let j=1;j<LOG;j++)for(let i=0;i+(1<<j)<=n;i++)this.table[i][j]=Math.min(this.table[i][j-1],this.table[i+(1<<(j-1))][j-1]);}
  query(l,r){const k=this.log2[r-l+1];return Math.min(this.table[l][k],this.table[r-(1<<k)+1][k]);}
}

