class SqrtDecomposition {
  constructor(arr){this.n=arr.length;this.B=Math.ceil(Math.sqrt(this.n));this.arr=[...arr];this.blocks=new Array(Math.ceil(this.n/this.B)).fill(0);for(let i=0;i<this.n;i++)this.blocks[Math.floor(i/this.B)]+=arr[i];}
  update(i,val){this.blocks[Math.floor(i/this.B)]+=val-this.arr[i];this.arr[i]=val;}
  query(l,r){let sum=0;const lBlock=Math.floor(l/this.B),rBlock=Math.floor(r/this.B);if(lBlock===rBlock){for(let i=l;i<=r;i++)sum+=this.arr[i];}else{for(let i=l;i<(lBlock+1)*this.B;i++)sum+=this.arr[i];for(let b=lBlock+1;b<rBlock;b++)sum+=this.blocks[b];for(let i=rBlock*this.B;i<=r;i++)sum+=this.arr[i];}return sum;}
}
function mosAlgorithm(arr,queries){
  const B=Math.ceil(Math.sqrt(arr.length));
  const sortedQ=queries.map((q,i)=>[...q,i]).sort((a,b)=>{const blockA=Math.floor(a[0]/B),blockB=Math.floor(b[0]/B);if(blockA!==blockB)return blockA-blockB;return blockA%2===0?a[1]-b[1]:b[1]-a[1];});
  let curL=0,curR=-1,curSum=0;const results=new Array(queries.length);
  for(const[l,r,origIdx]of sortedQ){while(curR<r)curSum+=arr[++curR];while(curL>l)curSum+=arr[--curL];while(curR>r)curSum-=arr[curR--];while(curL<l)curSum-=arr[curL++];results[origIdx]=curSum;}
  return results;
}
const mosAlgorithmImpl=mosAlgorithm;

