function canPartitionMeetMiddleImpl(nums){
  const n=nums.length;const total=nums.reduce((a,b)=>a+b,0);if(total%2!==0)return false;const target=total/2;
  const half=Math.floor(n/2);const left=nums.slice(0,half);const right=nums.slice(half);
  const leftSums=[];for(let mask=0;mask<(1<<left.length);mask++){let sum=0;for(let i=0;i<left.length;i++)if(mask&(1<<i))sum+=left[i];leftSums.push(sum);}leftSums.sort((a,b)=>a-b);
  for(let mask=0;mask<(1<<right.length);mask++){let sum=0;for(let i=0;i<right.length;i++)if(mask&(1<<i))sum+=right[i];const need=target-sum;let lo=0,hi=leftSums.length-1;while(lo<=hi){const mid=(lo+hi)>>1;if(leftSums[mid]===need)return true;if(leftSums[mid]<need)lo=mid+1;else hi=mid-1;}}
  return false;
}

function fourSumExistsOptimized(nums,target){
  const n=nums.length;const leftPairs=[];
  for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)leftPairs.push(nums[i]+nums[j]);
  leftPairs.sort((a,b)=>a-b);
  function binSearch(arr,val){let lo=0,hi=arr.length-1;while(lo<=hi){const mid=(lo+hi)>>1;if(arr[mid]===val)return true;if(arr[mid]<val)lo=mid+1;else hi=mid-1;}return false;}
  for(let i=0;i<n;i++)for(let j=i+1;j<n;j++){const need=target-nums[i]-nums[j];if(binSearch(leftPairs,need))return true;}
  return false;
}

