function _quickselect(arr,lo,hi,k){
  if(lo===hi)return arr[lo];
  const pivotIdx=lo+Math.floor(Math.random()*(hi-lo+1));
  [arr[pivotIdx],arr[hi]]=[arr[hi],arr[pivotIdx]];const pivot=arr[hi];
  let p=lo;for(let i=lo;i<hi;i++){if(arr[i]<=pivot){[arr[p],arr[i]]=[arr[i],arr[p]];p++;}}
